"use client";

/**
 * Shape story: a sentence told one beat at a time, centred. With each beat,
 * soft geometric shapes in primary tints burst out of the newest word, split
 * in two and drift into place behind the text, so the frame fills as the
 * sentence builds.
 *
 * Written by Better Design.
 */
import { loadFont } from "@remotion/google-fonts/InterTight";
import { Pie, Rect, Triangle } from "@remotion/shapes";
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER_TIGHT } = loadFont("normal", { weights: ["700"], subsets: ["latin"] });

/** Frames each beat holds before the next one. The last beat holds to the end. */
const BEAT_FRAMES = 40;
const SHAPES_PER_BEAT = 5;
const BURST_DELAY = 5;
const FLIGHT = 28;
/** Share of the flight after which each shape splits in two. */
const SPLIT_AT = 0.35;
const FONT_SIZE = 124;
/** Rough advance width of one character at the font size, used to find the newest word. */
const CHAR_WIDTH = 0.52;

export interface ShapeStoryProps {
  /** The sentence, one beat per entry. Each beat replaces the last in the centre. */
  beats?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter Tight. */
  font?: string;
}

type Kind = "circle" | "square" | "triangle";

interface Piece {
  kind: Kind;
  size: number;
  x: number;
  y: number;
  rotate: number;
  tint: number;
  gap: number;
}

/** Where one beat's shapes come to rest, seeded so every render matches. */
function piecesFor(beat: number): Piece[] {
  const kinds: Kind[] = ["circle", "square", "triangle"];
  return Array.from({ length: SHAPES_PER_BEAT }, (_, i) => {
    const r = (k: string) => random(`shape-story-${beat}-${i}-${k}`);
    const angle = ((i + r("a") * 0.7) / SHAPES_PER_BEAT) * Math.PI * 2 + beat * 0.9;
    return {
      kind: kinds[(i + beat) % kinds.length] ?? "circle",
      size: 70 + r("s") * 110,
      x: Math.cos(angle) * (560 + r("x") * 300),
      y: Math.sin(angle) * (290 + r("y") * 170),
      rotate: (r("r") - 0.5) * 120,
      tint: r("t"),
      gap: 18 + r("g") * 26,
    };
  });
}

/** Tell a sentence beat by beat while shapes burst from its newest word. */
export function ShapeStory({
  beats = ["Every idea", "begins small,", "then takes shape."],
  theme: themeOverride,
  font,
}: ShapeStoryProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER_TIGHT);

  const count = Math.max(1, beats.length);
  const index = Math.min(count - 1, Math.floor(frame / BEAT_FRAMES));
  const local = frame - index * BEAT_FRAMES;
  const text = beats[index] ?? "";
  const words = text.split(/\s+/).filter(Boolean);
  const lead = words.slice(0, -1).join(" ");
  const last = words[words.length - 1] ?? "";
  const enter = easings.out(progress(local, 0, 10));

  const tints = [
    withAlpha(theme.primary, 0.38),
    withAlpha(shiftHue(theme.primary, 30), 0.32),
    withAlpha(shiftHue(theme.primary, -35), 0.34),
    withAlpha(theme.primary, 0.2),
  ];

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      {beats.slice(0, index + 1).map((beatText, b) => {
        const start = b * BEAT_FRAMES + BURST_DELAY;
        const beatWords = beatText.split(/\s+/).filter(Boolean);
        const lastWord = beatWords[beatWords.length - 1] ?? "";
        // The newest word sits at the right end of the centred line.
        const origin = ((beatText.length - lastWord.length) * CHAR_WIDTH * FONT_SIZE) / 2;
        const dim = b < index ? 0.55 : 1;
        return piecesFor(b).map((piece, i) => {
          const t = progress(frame, start + i * 2, FLIGHT);
          const travel = easings.out(t);
          const split = easings.out(progress(t, SPLIT_AT, 1 - SPLIT_AT));
          const grow = easings.overshoot(progress(t, 0, 0.45));
          const x = origin + (piece.x - origin) * travel;
          const y = piece.y * travel;
          const color = tints[Math.floor(piece.tint * tints.length)] ?? tints[0];
          return (
            <div
              key={`${b}-${i}`}
              style={{
                position: "absolute",
                left: "50%",
                top: "50%",
                opacity: t > 0 ? dim : 0,
                transform: `translate(${x}px, ${y}px) translate(-50%, -50%) rotate(${piece.rotate * travel}deg) scale(${Math.max(0, grow)})`,
              }}
            >
              <Halves kind={piece.kind} size={piece.size} color={color} gap={piece.gap * split} />
            </div>
          );
        });
      })}
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div
          key={index}
          style={{
            fontSize: FONT_SIZE,
            fontWeight: 700,
            letterSpacing: "-0.04em",
            lineHeight: 1,
            whiteSpace: "nowrap",
            color: theme.foreground,
            opacity: enter,
            transform: `translateY(${(1 - enter) * 22}px)`,
          }}
        >
          {lead ? `${lead} ` : ""}
          <span style={{ color: theme.primary }}>{last}</span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}

/** One shape drawn as two halves that part by `gap` pixels. */
function Halves({ kind, size, color, gap }: { kind: Kind; size: number; color: string; gap: number }) {
  const half = gap / 2;
  const row = { display: "flex", alignItems: "center", gap } as const;
  if (kind === "circle") {
    return (
      <div style={row}>
        <Pie radius={size / 2} progress={0.5} rotation={Math.PI} fill={color} style={{ marginRight: -size / 2 }} />
        <Pie radius={size / 2} progress={0.5} fill={color} style={{ marginLeft: -size / 2 }} />
      </div>
    );
  }
  if (kind === "square") {
    return (
      <div style={row}>
        <Rect width={size / 2} height={size} fill={color} cornerRadius={Math.min(half, size * 0.12)} />
        <Rect width={size / 2} height={size} fill={color} cornerRadius={Math.min(half, size * 0.12)} />
      </div>
    );
  }
  return (
    <div style={{ ...row, gap: gap * 0.6 }}>
      <Triangle length={size * 0.62} direction="up" fill={color} cornerRadius={8} />
      <Triangle length={size * 0.62} direction="down" fill={color} cornerRadius={8} />
    </div>
  );
}
